// Generated by Claude (AI-assisted).
//
// A service worker that adds the two headers which make the book's pages
// "cross-origin isolated", for hosts where the headers cannot be configured.
//
// Lean in the browser runs several threads that share memory, and browsers
// allow shared memory only on pages served with
//     Cross-Origin-Opener-Policy: same-origin
//     Cross-Origin-Embedder-Policy: require-corp
// When the web server sends these itself, this worker is never registered.
// Otherwise `sfl-lean.js` registers it the first time a reader opens an
// exercise editor and reloads the page once; from then on this worker adds the
// headers to every response from the book's site.
//
// It must be served from the root of the HTML output so that its scope covers
// every chapter page.

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()));

self.addEventListener('fetch', (event) => {
  const request = event.request;
  // Requests the browser may only answer from its cache cannot be re-fetched.
  if (request.cache === 'only-if-cached' && request.mode !== 'same-origin') return;
  event.respondWith(
    fetch(request).then((response) => {
      // An opaque response (cross-origin, no CORS) cannot be rewritten.
      if (response.status === 0) return response;
      const headers = new Headers(response.headers);
      headers.set('Cross-Origin-Opener-Policy', 'same-origin');
      headers.set('Cross-Origin-Embedder-Policy', 'require-corp');
      return new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers,
      });
    }),
  );
});
